package net.civeira.phylax.feature.observe.observedalert.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlertStatusOptions;

class StatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property status of observed alert ")
  void test_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom("_FIRING_"));
    Assertions.assertEquals(ObservedAlertStatusOptions.FIRING,
        StatusVO.tryFrom("FIRING").getStatus());
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom(null));
    Assertions.assertEquals(ObservedAlertStatusOptions.FIRING,
        StatusVO.from(ObservedAlertStatusOptions.FIRING).getStatus());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedAlertStatusOptions.FIRING + "]",
        StatusVO.from(ObservedAlertStatusOptions.FIRING).toString());
  }
}
